mapper.insert:
/* PEAAutoChargeDAO.insertChrgAcnt */
INSERT INTO AP_CUST_CHRG_ACNT_MNG (
    MCUST_NO
  , ACNT_SEQ
  , CUST_KEY
  , BILL_KEY
  , BANK_GBCD
  , BANK_ACNT_NM
  , ACNT_NO
  , RGST_ID
  , RGST_IP
  , REG_DTM
  , CHGP_ID
  , CHGP_IP
  , CHG_DTM
) VALUES (
    #{mcustNo}
  , #{acntSeq}
  , #{custKey}
  , #{billKey}
  , #{bankGbcd}
  , #{bankAcntNm, jdbcType=VARCHAR}
  , #{acntNo, jdbcType=VARCHAR}
  , #{rgstId}
  , #{rgstIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , #{chgpId}
  , #{chgpIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
)

mapper.select:
/* PEAAutoChargeDAO.selectChrgAcntList */
SELECT

FROM
    AP_CUST_CHRG_ACNT_MNG


        AND MCUST_NO = #{mcustNo}


        AND ACNT_SEQ = #{acntSeq}


ORDER BY
    LVL_PRTY ASC

/* PEAAutoChargeDAO.selectMaxAcntSeq */
SELECT MAX(ACNT_SEQ) AS ACNT_SEQ
FROM AP_CUST_CHRG_ACNT_MNG
WHERE MCUST_NO = #{mcustNo}

mapper.insert:
/* PEAAutoChargeDAO.insertAutoChrgReqDtl */
INSERT INTO AP_CUST_AUTO_CHRG_REQ_DTL (
    MCUST_NO
  , AUTO_CHRG_YN
  , PTY1_ACNT_SEQ
  , PTY2_ACNT_SEQ
  , RGST_ID
  , RGST_IP
  , REG_DTM
  , CHGP_ID
  , CHGP_IP
  , CHG_DTM
) VALUES (
    #{mcustNo}
  , #{autoChrgYn}
  , #{pty1AcntSeq}
  , #{pty2AcntSeq}
  , #{rgstId}
  , #{rgstIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , #{chgpId}
  , #{chgpIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
)

/* PEAAutoChargeDAO.insertPntAutoChrgHis */
INSERT INTO AP_CUST_PNT_AUTO_CHRG_HIS (
    LOG_ID
  , EXEC_DTM
  , MCUST_NO
  , ORD_ID
  , PAY_KEY
  , CHRG_TYPE_GBCD
  , RSV_CHRG_MTHD_GBCD
  , RSV_CHRG_PRD_GBCD
  , RSV_CHRG_DLU_GBCD
  , RSV_BSIC_AMT_GBCD
  , ACNT_CHRG_AMT
  , REAL_CHRG_AMT
  , ACNT_SEQ
  , BANK_GBCD
  , ACNT_NO
  , PROC_RST_GBCD
  , ERR_CD
  , ERR_MSG_CNTN
  , BANK_ACNT_NM
) VALUES (
    (SELECT NVL(MAX(LOG_ID), 0) + 1 FROM AP_CUST_PNT_AUTO_CHRG_HIS)
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , #{mcustNo}
  , #{orderId, jdbcType=VARCHAR}
  , #{paymentKey, jdbcType=VARCHAR}
  , #{chrgTypeGbcd}
  , #{rsvChrgMthdGbcd}
  , #{rsvChrgPrdGbcd}
  , #{rsvChrgDtGbcd, jdbcType=VARCHAR}
  , #{rsvBsicAmtGbcd, jdbcType=VARCHAR}
  , #{acntChrgAmt}
  , #{realChrgAmt}
  , #{acntSeq}
  , #{bankGbcd}
  , #{acntNo}
  , #{procRstGbcd}
  , #{errCd}
  , #{errMsgCntn}
  , #{bankAcntNm, jdbcType=VARCHAR}
)

