/* PEAAutoChargeDAO.insertPntPrtyChgHis */
INSERT INTO AP_CUST_PNT_PRTY_CHG_HIS (
    MCUST_NO
  , SEQ
  , PNT_TYPE_GBCD
  , RGST_ID
  , RGST_IP
  , REG_DTM
  , CHGP_ID
  , CHGP_IP
  , CHG_DTM
) VALUES (
    #{mcustNo}
  , AP_CUST_PNT_PRTY_CHG_HIS_SEQ.NEXTVAL
  , #{pntTypeGbcd}
  , #{rgstId}
  , #{rgstIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , #{chgpId}
  , #{chgpIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
)

